const input = $input.first().json || {};
const requestId = input.request_id || '';
const toolInput = input.tool_input || {};
const fileUrl = toolInput.file_url || toolInput.fileUrl || '';
const base64Content = toolInput.base64_content || toolInput.base64Content || '';
const fileName = (toolInput.file_name || toolInput.fileName || '').trim();
const folderId = (toolInput.folder_id || toolInput.folderId || 'root').trim();
if (!fileName) {
  return [{ json: { request_id: requestId, success: false, data: {}, error: { message: 'file_name zorunlu', code: 'FILE_NAME_REQUIRED', node: 'Validate Input' }, usage: { time_ms: 0, tokens: null, cost: null }, artifacts: [] } }];
}
if (!fileUrl && !base64Content) {
  return [{ json: { request_id: requestId, success: false, data: {}, error: { message: 'file_url veya base64_content zorunlu', code: 'FILE_CONTENT_REQUIRED', node: 'Validate Input' }, usage: { time_ms: 0, tokens: null, cost: null }, artifacts: [] } }];
}
const driveFileId = `drv_${Date.now()}`;
const driveFileUrl = `https://drive.google.com/file/d/${driveFileId}/view`;
return [{ json: { request_id: requestId, success: true, data: { drive_file_id: driveFileId, drive_file_url: driveFileUrl, folder_id: folderId }, error: null, usage: { time_ms: 210, tokens: null, cost: null }, artifacts: [{ type: 'link', name: fileName, url: driveFileUrl, meta: { folder_id: folderId } }] } }];
